multi_queries.type_and_summary:
PREFIX hist: <http://www.example.org/korean-history#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "갑신정변" || ?entityLabel = "갑오개혁" || ?entityLabel = "1884년 갑신정변 가담 및 도승지 임명" || ?entityLabel = "Event_1894: 1894년 갑오개혁 때 폐지" || ?entityLabel = "1894년 갑오개혁" || ?entityLabel = "갑오개혁법" || ?entityLabel = "임오군란" || ?entityLabel = "면리제 개편 추진" || ?entityLabel = "무토궁방전 폐지" || ?entityLabel = "갑오경장")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

